# Generated by Cursor (plan: trailing-dash accept rule)
"""Scan for tokens that are word + trailing dash-like (interruptions); accept (identity)."""

import re

# Word chars + optional spaces + one trailing dash-like; dash not followed by word char. Edited by Cursor.
TRAILING_DASH_ACCEPT_RE = re.compile(r"\b(\w+\s*[-\u2011\u2013\u2014\u2015])(?=\s|$)")

RULE_ID = "trailing_dash_accept"


def scan_turn_trailing_dash_accept(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """Emit (trailing_dash_accept, start_index, span, path_str) for each match."""
    result: list[tuple[str, int, str, str]] = []
    for m in TRAILING_DASH_ACCEPT_RE.finditer(text):
        result.append((RULE_ID, m.start(), m.group(1), path_str))
    return result
